    "questionAr": "سلسلة ماركوف متقطعة ذات حالتين مصفوفة انتقالها $P = \\begin{pmatrix} P_{11} & P_{12} \\\\ P_{21} & P_{22} \\end{pmatrix}$. إذا كان $P_{11} = 0.18$، فأوجد احتمال الانتقال $P_{12}$.",
