    "questionAr": "درجات اختبار قدرات موزعة توزيعاً طبيعياً بمتوسط $\\mu = 65$ وانحراف معياري $\\sigma = 10$. إذا علمت أن $\\Phi(1.96) = 0.975$، فأوجد الدرجة $x$ التي تقع تحتها $97.5\\%$ من المشاهدات.",
