    "questionEn": "In a stochastic process, a random sample of size $n = 100$ yields a sample mean $\bar{x} = 116$. The population standard deviation is known to be $\sigma = 15$. Construct a $95\%$ confidence interval for the population mean $\mu$ (use $z^* = 1.96$).",
    "questionAr": "في عملية عشوائية احتمالية، أعطت عينة عشوائية حجمها $n = 100$ متوسطاً قدره $\bar{x} = 116$. والانحراف المعياري للمجتمع معلوم $\sigma = 15$. أنشئ فترة ثقة $95\%$ للمتوسط العام $\mu$ (استخدم $z^* = 1.96$).",
