    "questionEn": "Under random sampling conditions, a 2-state regular Markov chain has transition matrix $P = \begin{pmatrix} 1 - \frac{1}{7} & \frac{1}{7} \\ \frac{1}{2} & \frac{1}{2} \end{pmatrix}$. Find the stationary distribution vector $\pi = (\pi_1, \pi_2)$ satisfying $\pi P = \pi$ and $\pi_1 + \pi_2 = 1$.",
    "questionAr": "تحت شروط المعاينة العشوائية، سلسلة ماركوف منتظمة ذات حالتين مصفوفة انتقالها $P = \begin{pmatrix} 1 - \frac{1}{7} & \frac{1}{7} \\ \frac{1}{2} & \frac{1}{2} \end{pmatrix}$. أوجد متجه التوزيع المستقر $\pi = (\pi_1, \pi_2)$ الذي يحقق $\pi P = \pi$ و $\pi_1 + \pi_2 = 1$.",
