    "questionAr": "لتكن $X_1, X_2, \\dots, X_n$ عينة عشوائية مستقلة ومتطابقة من توزيع أسي دالة كثافته $f(x; \\lambda) = \\lambda e^{-\\lambda x}$ حيث $x > 0$ و $\\lambda > 0$. استنتج مقدر الإمكان الأكبر (MLE) للمعلَمة $\\lambda$.",
