      "2. Differentiate w.r.t $\\mu$: $\\frac{d}{d\\mu}\\ln L = \\frac{1}{\\sigma_0^2}\\sum_{i=1}^n (X_i - \\mu) = 0$.",
      "3. $\\sum_{i=1}^n X_i - n\\mu = 0 \\implies \\hat{\\mu}_{\\text{MLE}} = \\frac{1}{n}\\sum_{i=1}^n X_i = \\bar{X}$."
