    "questionAr": "لتكن $X_1, \\dots, X_n$ عينة مستقلة ومتطابقة من توزيع هندسي بدالة كتلة $P(X = x) = (1-p)^{x-1} p$ حيث $x \\in \\{1, 2, 3, \\dots\\}$. استنتج مقدر الإمكان الأكبر $\\hat{p}$.",
