      "4. Solving yields $n(1-p) = p(\\sum X_i - n) \\implies n = p\\sum X_i \\implies \\hat{p}_{\\text{MLE}} = \\frac{n}{\\sum_{i=1}^n X_i} = \\frac{1}{\\bar{X}}$."
