      "٢. لوغاريتم الإمكان: $\\ln L(p) = n\\ln p + (\\sum X_i - n)\\ln(1-p)$.",
      "٣. بمساواة المشتقة بالصفر: $\\frac{n}{p} - \\frac{\\sum X_i - n}{1-p} = 0$.",
      "٤. ينتج أن $n = p\\sum X_i \\implies \\hat{p}_{\\text{MLE}} = \\frac{n}{\\sum X_i} = \\frac{1}{\\bar{X}}$."
