      "$\\hat{\\theta}_{\\text{MLE}} = -\\frac{\\sum_{i=1}^n \\ln X_i}{n}$",
      "$\\hat{\\theta}_{\\text{MLE}} = -\\frac{n}{\\sum_{i=1}^n \\ln X_i}$"
