    "questionAr": "لأي توزيع احتمالي له متوسط منتهٍ $\\mu$ وانحراف معياري $\\sigma$، ما هو الحد الأقصى لاحتمال أن تنحرف مشاهدة عن المتوسط بمقدار 3 انحرافات معيارية على الأقل ($P(|X - \\mu| \\ge 3\\sigma)$)؟",
