    "questionAr": "لتكن $Z_1, Z_2, \\dots, Z_k$ متغيرات طبيعية معيارية مستقلة. مجموع مربعاتها $Q = \\sum_{i=1}^k Z_i^2$ يتبع توزيع كاي-تربيع بـ $k$ درجات حرية. ما هو تباين هذا المجموع $\\text{Var}(Q)$؟",
